"""Render a schema as a Markdown page for the documentation."""

from __future__ import annotations


def render_markdown(schema: dict) -> str:
    lines = [
        f"# {schema['product']}",
        "",
        _text(schema["description"]),
        "",
        f"Schema version {schema['schema_version']} ({schema['status']}).",
        "",
    ]

    if "file" in schema:
        lines += ["## File", "", _text(schema["file"]["description"]), ""]
        if "filename_pattern" in schema["file"]:
            lines += [f"Filename pattern: `{schema['file']['filename_pattern']}`", ""]

    if "model" in schema:
        lines += ["## Model", ""]
        for name, text in schema["model"].items():
            lines += [
                f"### {name.capitalize()}",
                "",
                "```text",
                text.rstrip(),
                "```",
                "",
            ]

    lines += [
        "## Dimensions",
        "",
        "| Name | Description |",
        "| --- | --- |",
        *(
            f"| `{name}` | {_cell(dim['description'])} |"
            for name, dim in schema["dimensions"].items()
        ),
        "",
    ]

    if schema.get("attributes"):
        lines += [
            "## Global attributes",
            "",
            *_attribute_table(schema["attributes"]),
            "",
        ]

    lines += ["## Variables", "", *_variable_table(schema["variables"]), ""]

    for name, group in schema.get("groups", {}).items():
        lines += [
            f"## Group `{name}`",
            "",
            _text(group["description"]),
            "",
            *_variable_table(group["variables"]),
            "",
        ]

    if schema.get("constraints"):
        lines += ["## Constraints", ""]
        lines += [
            f"- **`{constraint['id']}`**: {_text(constraint['rule'])}"
            for constraint in schema["constraints"]
        ]
        lines.append("")

    if schema.get("open_questions"):
        lines += ["## Open questions", ""]
        lines += [
            f"- **{question['id']}**: {_text(question['question'])} "
            f"{_text(question['context'])}"
            for question in schema["open_questions"]
        ]
        lines.append("")

    return "\n".join(lines)


def _variable_table(variables: dict) -> list[str]:
    rows = [
        "| Name | Dimensions | Type | Units | Required | Range | Role | Description |",
        "| --- | --- | --- | --- | --- | --- | --- | --- |",
    ]
    for name, field in variables.items():
        dims = ", ".join(field["dims"]) if field["dims"] else "scalar"
        rows.append(
            f"| `{name}` | {dims} | {field['dtype']} | {_units(field)} "
            f"| {_required(field)} | {_range(field)} | {field.get('role', '')} "
            f"| {_cell(field['description'])} |"
        )
    return rows


def _attribute_table(attributes: dict) -> list[str]:
    rows = [
        "| Name | Type | Required | Range | Description |",
        "| --- | --- | --- | --- | --- |",
    ]
    rows += [
        f"| `{name}` | {field['dtype']} | {_required(field)} | {_range(field)} "
        f"| {_cell(field['description'])} |"
        for name, field in attributes.items()
    ]
    return rows


def _units(field: dict) -> str:
    return f"`{field['units']}`" if "units" in field else ""


def _required(field: dict) -> str:
    if field.get("required"):
        return "yes"
    if "required_when" in field:
        conditions = " and ".join(
            f"{name} = {_value(value)}"
            for name, value in field["required_when"].items()
        )
        return f"when {conditions}"
    if "default" in field:
        return f"no (default {_value(field['default'])})"
    return "no"


def _range(field: dict) -> str:
    if "allowed" in field:
        return ", ".join(str(value) for value in field["allowed"])
    low, high = field.get("valid_min"), field.get("valid_max")
    if low is not None and high is not None:
        return f"[{low}, {high}]"
    if low is not None:
        return f"≥ {low}"
    if high is not None:
        return f"≤ {high}"
    return ""


def _value(value) -> str:
    if isinstance(value, bool):
        return str(value).lower()
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def _text(text: str) -> str:
    """Collapse a folded YAML string onto one line."""
    return " ".join(str(text).split())


def _cell(text: str) -> str:
    return _text(text).replace("|", "\\|")
